public class UndoableTextEditorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        UndoableTextEditor editor = new UndoableTextEditor();
        editor.append("hi");
        check("text after one append", "hi", editor.text());
        editor.append(" there");
        check("text after two appends", "hi there", editor.text());
        check("history size after two appends", 2, editor.historySize());

        editor.deleteLast(6);
        check("text after deleteLast(6)", "hi", editor.text());
        check("history size after the delete", 3, editor.historySize());

        check("undo reports success", true, editor.undo());
        check("text after undoing the delete", "hi there", editor.text());
        editor.undo();
        check("text after undoing the second append", "hi", editor.text());
        editor.undo();
        check("text after undoing everything", "", editor.text());
        check("history is empty again", 0, editor.historySize());
        check("undo on an empty history", false, editor.undo());

        UndoableTextEditor small = new UndoableTextEditor();
        small.append("abc");
        small.deleteLast(99);
        check("deleteLast beyond the end", "", small.text());
        small.undo();
        check("undo restores the whole text", "abc", small.text());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

