import java.util.ArrayDeque;
import java.util.Deque;

interface EditCommand {

    void run();

    void undo();
}

public class UndoableTextEditor {

    private String text = "";
    private final Deque<EditCommand> history = new ArrayDeque<>();

    public void append(String s) {
        EditCommand command = new EditCommand() {
            @Override
            public void run() {
                setText(text() + s);
            }

            @Override
            public void undo() {
                String current = text();
                setText(current.substring(0, current.length() - s.length()));
            }
        };
        command.run();
        history.push(command);
    }

    public void deleteLast(int n) {
        String current = text;
        int count = Math.min(Math.max(n, 0), current.length());
        String removed = current.substring(current.length() - count);
        EditCommand command = new EditCommand() {
            @Override
            public void run() {
                String now = text();
                setText(now.substring(0, now.length() - count));
            }

            @Override
            public void undo() {
                setText(text() + removed);
            }
        };
        command.run();
        history.push(command);
    }

    public boolean undo() {
        if (history.isEmpty()) {
            return false;
        }
        history.pop().undo();
        return true;
    }

    public String text() {
        return text;
    }

    public int historySize() {
        return history.size();
    }

    // Helper you may use from your commands.
    private void setText(String value) {
        this.text = value;
    }
}
